int findBucketMax(const std::vector<int>& buckets) {
    for (int i = buckets.size() - 1; i >= 0; i--) {
        if (buckets[i] > 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    int n, B;
    std::cin >> n >> B;
    std::vector<int> arr(n);
    for (int index = 0; index < n; index++) {
        std::cin >> arr[index];
    }

    std::vector<int> buckets(101, 0);
    int totalSum = 0;

    int evenCount = 0;
    int oddCount = 0;
    int startIndex = 0;
    int totalCount = 0;
    int pointer = 1;

    for (int i = 0; i < n - 1; i++) {
        if (arr[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }

        if (evenCount == oddCount) {
            int diff = std::abs(arr[i + 1] - arr[i]);
            int maxBucket = findBucketMax(buckets);
            if (totalSum > B && diff < maxBucket) {
                totalSum -= maxBucket;
                buckets[maxBucket]--;
                buckets[diff]++;
                totalSum += diff;
            } else if (totalSum < B) {
                totalSum += diff;
                buckets[diff]++;
                totalCount++;
                startIndex = i + 1;
            }
            if (i == n - 2 && pointer < n - 1) {
                i = startIndex++;
                evenCount = 0;
                oddCount = 0;
            }
        }
    }

    int i = buckets.size() - 1;
    while (totalSum > B && i >= 0) {
        if (buckets[i] > 0) {
            totalSum -= i;
            totalCount--;
        } else {
